import AppKit
import DSStore
import Foundation
import ImageIO
import Testing
@testable import Stow

/// A redistributable, self-authored image keeps the real-corpus failures covered in ordinary CI.
/// Generated by scripts/make-fixtures.sh --compatibility-only; no third-party archive bytes.
@Suite("Realistic installer compatibility fixture", .enabled(if: SevenZip.bundled() != nil, "7zz isn't bundled"))
@MainActor
struct InstallerCompatibilityFixtureTests {
    private let volume = "Compatibility Tool v8.0 测试"

    private func open() async throws -> (Archive, TemporaryFolder) {
        let folder = try TemporaryFolder()
        let file = folder.url.appending(path: "Fixture-Compatibility.dmg")
        try FileManager.default.copyItem(at: try InstallEngineTests.fixture("Fixture-Compatibility.dmg"), to: file)
        let listing = try await ArchiveEngine.shared.list(file)
        let alias = try #require(listing.entries.first { $0.path == volume + "/Applications" })
        #expect(!alias.isFolder && !alias.isSymlink)
        return (await DiskImageAliasLoader.prepare(Archive(listing: listing, url: file), password: nil), folder)
    }

    @Test func readsAnEightKiBLeafRootRetinaPictureBookmarkAndNamedIconThroughXPC() async throws {
        let (archive, folder) = try await open()
        defer { folder.cleanUp() }
        let app = volume + "/Compatibility Tool.app"
        let store = volume + "/.DS_Store"
        let background = volume + "/.background.tiff"
        #expect(archive.volumeRoot == volume)
        #expect(archive.children(of: volume).map(\.name) == ["Compatibility Tool.app", "Read Me.txt"])
        #expect(archive.dropTargets == [.init(path: volume + "/Applications", folder: "/Applications")])
        #expect(archive.entry(at: volume + "/Applications")?.isHelper == true)
        #expect(archive.entry(at: background)?.isHelper == true)
        #expect(archive.presentationFiles[store] == 16_388)
        #expect(archive.presentationFiles[background] != nil)

        let source = try #require(archive.source)
        let files = try await ArchiveFileReader.read([
            store: 16_388, background: 8 << 20, app + "/Contents/Info.plist": 1 << 20,
        ], from: archive, source: source, password: nil)
        let storeData = try #require(files[store])
        func word(at offset: Int) -> UInt32 {
            storeData[offset..<(offset + 4)].reduce(0) { ($0 << 8) | UInt32($1) }
        }
        let allocator = Int(word(at: 8)) + 4
        let rootNode = Int(word(at: 36))
        let address = word(at: allocator + 8 + rootNode * 4)
        #expect(word(at: 52) == 4_096) // Logical page size and leaf allocation are distinct.
        #expect(1 << (address & 31) == 8_192)
        let parsed = try DSStore.read(from: storeData)
        #expect(parsed.iconPosition(for: "Compatibility Tool.app")?.x == 130)
        #expect(parsed.iconPosition(for: "Applications")?.x == 410)
        let plist = try #require(files[app + "/Contents/Info.plist"])
        let info = try #require(PropertyListSerialization.propertyList(from: plist, format: nil) as? [String: Any])
        #expect(info["CFBundleIconFile"] == nil)
        #expect(info["CFBundleIconName"] as? String == "Compatibility")
        #expect(ArchivedAppIcon.iconFile(app: app, plist: plist, in: archive) == app + "/Contents/Resources/Compatibility.icns")
        let picture = try #require(files[background])
        let imageSource = try #require(CGImageSourceCreateWithData(picture as CFData, nil))
        #expect(CGImageSourceGetCount(imageSource) == 2)

        let canvas = try #require(await InstallerCanvasLoader.load(archive, password: nil))
        #expect(canvas.background != nil)
        #expect(canvas.backgroundSize == CGSize(width: 540, height: 380))
        #expect(canvas.layout.background == .picture(volumePaths: ["/.background.tiff"]))
        #expect(canvas.layout.windowSize == CGSize(width: 540, height: 352))
        #expect(canvas.layout.iconSize == 80 && canvas.layout.textSize == 12)
        #expect(canvas.layout.positions["Compatibility Tool.app"] == CGPoint(x: 130, y: 220))
        #expect(canvas.layout.positions["Applications"] == CGPoint(x: 410, y: 220))
        #expect(canvas.icons[app] != nil)
        #expect(TemporaryFolder.contents(of: folder.url) == ["Fixture-Compatibility.dmg"])
    }

    @Test func extractAllKeepsTheAppButLeavesTheAuthoredPresentationBehind() async throws {
        let (archive, folder) = try await open()
        defer { folder.cleanUp() }
        let output = folder.url.appending(path: "Output", directoryHint: .isDirectory)
        try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true)
        _ = try await Extraction.run(archive, selection: nil, to: output) { _ in }
        let names = TemporaryFolder.contents(of: output)
        #expect(names.contains { $0.hasSuffix("Compatibility Tool.app/Contents/MacOS/Compatibility Tool") })
        #expect(names.contains { $0.hasSuffix("Compatibility Tool.app/Contents/Resources/Compatibility.icns") })
        #expect(names.contains { $0.hasSuffix("Read Me.txt") })
        #expect(!names.contains { $0.hasSuffix(".DS_Store") || $0.hasSuffix(".background.tiff") || $0.hasSuffix("Applications") })
        #expect(!names.contains { $0.hasPrefix(".stow-staging-") })
    }
}
